#!/usr/bin/env bash
# The default-options test. features.yml runs only the scenarios
# (--skip-autogenerated): this feature has no default pin, so installing it
# with its defaults fails by design and this script is not reached there. It
# is kept for a local run that supplies a pin through the image (for example
# `devcontainer features test -f cli-mosquitto -i <image with
# CLI_MOSQUITTO_VERSION in its ENV>`).
set -e

# shellcheck source=/dev/null
source dev-container-features-test-lib

check "mosquitto_pub is on PATH" command -v mosquitto_pub
check "mosquitto_sub is on PATH" command -v mosquitto_sub
check "mosquitto_rr is on PATH" command -v mosquitto_rr

reportResults
